exports.template:
# Generated by the cloud-native guide site
# Kubespray release: {{choice.kubespray}}

kube_version: {{version.kubernetes}}
kube_network_plugin: {{choice.cni}}
kube_proxy_mode: ""
kube_pods_subnet: "{{value.podCidr}}"
kube_service_addresses: "{{value.serviceCidr}}"
k8sServiceHost: "{{value.apiServerIp}}"
k8sServicePort: 6443
enable_coredns: true

# Generated by the cloud-native guide site
# Edge nodes: {{value.edgeNodes}}

global_defs {
    router_id {{value.clusterName}}-lb-1
    enable_script_security
    script_user root
    vrrp_skip_check_adv_addr
}

vrrp_script chk_haproxy {
    script "/etc/keepalived/keepalived.d/check_haproxy.sh"
    interval 2
    weight -20
    fall 2
    rise 2
}

vrrp_instance VI_EDGE {
    state BACKUP
    interface bond0
    virtual_router_id 51
    priority 100
    advert_int 1

    authentication {
        auth_type PASS
        auth_pass {{vrrpAuthPass}}
    }

    unicast_src_ip {{value.edgeL1}}
    unicast_peer {
        {{value.edgeL2}}
    }

    virtual_ipaddress {
        {{value.edgeVip}}/24
    }

    track_script {
        chk_haproxy
    }

    notify_master "/etc/keepalived/keepalived.d/notify.sh MASTER"
    notify_backup "/etc/keepalived/keepalived.d/notify.sh BACKUP"
}

# Generated by the cloud-native guide site
# Namespace: {{value.appNamespace}}
# Secret engine: {{value.vaultEngine}}

path "{{value.vaultEngine}}/apps/{{value.appNamespace}}/*" {
  capabilities = ["read"]
}

path "database/creds/{{value.appNamespace}}/*" {
  capabilities = ["read"]
}

path "pki/issue/{{value.appNamespace}}" {
  capabilities = ["create", "update"]
}
